  `transaction_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transaction_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `points_change` bigint NOT NULL,
  `order_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `redemption_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference_transaction_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lot_expiry_date` date DEFAULT NULL,
  `expiry_batch_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transaction_date` datetime NOT NULL,
  PRIMARY KEY (`transaction_id`),
  KEY `account_id` (`account_id`),
  KEY `order_id` (`order_id`),
  KEY `redemption_id` (`redemption_id`),
  KEY `reference_transaction_id` (`reference_transaction_id`),
  KEY `expiry_batch_id` (`expiry_batch_id`),
  CONSTRAINT `pointstransaction_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `loyaltyaccount` (`account_id`),
  CONSTRAINT `pointstransaction_ibfk_2` FOREIGN KEY (`order_id`) REFERENCES `order` (`order_id`),
  CONSTRAINT `pointstransaction_ibfk_3` FOREIGN KEY (`redemption_id`) REFERENCES `redemption` (`redemption_id`),
  CONSTRAINT `pointstransaction_ibfk_4` FOREIGN KEY (`reference_transaction_id`) REFERENCES `pointstransaction` (`transaction_id`),
  CONSTRAINT `pointstransaction_ibfk_5` FOREIGN KEY (`expiry_batch_id`) REFERENCES `expiry_batch_run` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
